let range (lo : int) (hi : int) : int list =
  let rec loop (i : int) (acc : int list) : int list =
    if i < lo then acc else loop (i - 1) (i :: acc)
  in
  loop hi []

let merge (l1 : int list) (l2 : int list) : int list =
  let rec loop (l1 : int list) (l2 : int list) (acc : int list) : int list =
    begin match l1, l2 with
    | [], rest | rest, [] ->
      let rec finish (r : int list) (acc : int list) : int list =
        begin match r with [] -> List.rev acc | x :: tl -> finish tl (x :: acc) end in
      finish rest acc
    | x :: t1, y :: t2 ->
      if x <= y then loop t1 l2 (x :: acc) else loop l1 t2 (y :: acc)
    end
  in
  loop l1 l2 []

let fib (n : int) : int =
  let rec loop (i : int) (a : int) (b : int) : int =
    if i = 0 then a else loop (i - 1) b (a + b)
  in
  loop n 0 1

