(* Test helpers: very deep, one-sided trees, built tail recursively. *)
(* left_chain n: values 1..n, each node's left child holds the previous value. *)
let left_chain (n : int) : int tree =
  let rec go (i : int) (acc : int tree) : int tree =
    if i > n then acc else go (i + 1) (Node (acc, i, Empty)) in
  go 1 Empty

