type 'a queue = { mutable head : 'a qnode option; mutable tail : 'a qnode option }

let create () : 'a queue = { head = None; tail = None }

let enq (x : 'a) (q : 'a queue) : unit =
  let newnode = { v = x; next = None } in
  begin match q.tail with
  | None -> q.head <- Some newnode; q.tail <- Some newnode
  | Some n -> n.next <- Some newnode; q.tail <- Some newnode
  end

