let remove_all (x : 'a) (q : 'a queue) : unit =
  let rec go (cur : 'a qnode option) : 'a qnode option =
    begin match cur with
    | None -> None
    | Some n ->
      let rest = go n.next in
      if n.v = x then rest else (n.next <- rest; Some n)
    end
  in
  q.head <- go q.head;
  let rec last (no : 'a qnode option) (seen : 'a qnode option) : 'a qnode option =
    begin match no with None -> seen | Some n -> last n.next no end in
  q.tail <- last q.head None

