let record_all (s : stats) (l : int list) : int =
  let rec loop (l : int list) (n : int) : int =
    begin match l with
    | [] -> n
    | x :: tl ->
      s.count <- s.count + 1;
      s.total <- s.total + x;
      s.largest <- (match s.largest with Some m when m >= x -> Some m | _ -> Some x);
      loop tl (n + 1)
    end
  in
  loop l 0

