practice.solution:
let drain (s : 'a stack) (f : 'a -> unit) : int =
  let rec loop (n : int) : int =
    begin match s.items with
    | [] -> n
    | x :: rest ->
      s.items <- rest;
      f x;
      loop (n + 1)
    end
  in
  loop 0

practice.nonTail:
let rec drain (s : 'a stack) (f : 'a -> unit) : int =
  begin match s.items with
  | [] -> 0
  | x :: rest ->
    s.items <- rest;
    f x;
    1 + drain s f
  end

practice.tests:
;; run_test "empty stack" (fun () ->
  drain (stack_of_list []) (fun _ -> ()) = 0)
;; run_test "pops top first" (fun () ->
  let seen = ref [] in let n = drain (stack_of_list [3; 2; 1]) (fun x -> seen := x :: !seen) in n = 3 && !seen = [1; 2; 3])
;; run_test "leaves the stack empty" (fun () ->
  let s = stack_of_list ["a"; "b"] in ignore (drain s (fun _ -> ())); s.items = [])
;; run_test "f sees the stack already popped" (fun () ->
  let s = stack_of_list [1; 2] in let sizes = ref [] in ignore (drain s (fun _ -> sizes := List.length s.items :: !sizes)); !sizes = [0; 1])
;; run_test "tail recursive: a very tall stack" (fun () ->
  let total = ref 0 in drain (stack_of_list (tr_init stress_n (fun i -> i))) (fun x -> total := !total + 1) = stress_n && !total = stress_n)
